// Vector Random Access Optimization (O(1))
std::vector<uint32_t> data(1000);
uint32_t index = 500;

// 1. Standard, Optimized Access (Unchecked)
// Relies purely on contiguous memory layout.
uint32_t fast_val = data[index];

// 2. Underlying Implementation: Raw Pointer Arithmetic
// data.data() provides the contiguous base address.
uint32_t* base_ptr = data.data();

// Compiler optimizes data[index] to direct offset calculation:
uint32_t raw_val = *(base_ptr + index);

// Optimization Notes:
// - Vector size/type known: Memory offsets are constant.
// - Avoids runtime bounds check (unlike data.at(index)).
// - Cache coherence is critical for performance maximization.
